/*
    INSPEC - Import Lighting + Parking map geometry
    Source workbook: map pointing lightning & carpark.xlsx

    Map masters:
      - dbo.INSPEC_M_LightingMap: MapID 1 (LOGO), 3 (SIGNBOARD), 7 (OUTDOOR)
      - dbo.INSPEC_M_ParkingMap : MapID 4 (B2_GKBI), 5 (B3_GKBI), 6 (B1_GKBI)
      - dbo.PIP_M_InspectionMap : FK parent rows mirrored with the same MapIDs
      ImagePath is stored as the relative IIS path supplied for each map.

    Inspection points:
      - dbo.PIP_M_InspectionPoint
      - MapID follows the exact MapID in the two master-map tables above and is mirrored
        to dbo.PIP_M_InspectionMap because of FK_PIP_M_InspectionPoint_Map.
      - InspectionPointID is assigned deterministically from 1 through 798,
        ordered by MapID, DisplayOrder, then PointCode.
      - This script stops if IDs 1..798 conflict with unrelated/renumbered rows;
        it does not silently overwrite unrelated point records.

    Geometry:
      - SvgPathData and CIRCLE attributes remain in original workbook coordinates.
      - MapX/MapY remain percentage anchors (0..100).
      - ViewBox uses the source drawing dimensions supplied in the map masters.

    SAFETY:
      @ApplyChanges = 0 : preview only; transaction is rolled back.
      Set @ApplyChanges = 1 after reviewing the preview to commit.
      Existing maps are reused/updated by their fixed MapID + CompanyID + LocationID.
      Existing points are matched by MapID + PointCode and keep their expected ID.
*/

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @ApplyChanges BIT;
DECLARE @UserID VARCHAR(50);
SET @ApplyChanges = 0; -- CHANGE TO 1 TO COMMIT
SET @UserID = 'SYSTEM';

IF COL_LENGTH('dbo.PIP_M_InspectionPoint','MapX') IS NULL
 OR COL_LENGTH('dbo.PIP_M_InspectionPoint','MapY') IS NULL
 OR COL_LENGTH('dbo.PIP_M_InspectionPoint','ShapeType') IS NULL
 OR COL_LENGTH('dbo.PIP_M_InspectionPoint','SvgPathData') IS NULL
 OR COL_LENGTH('dbo.PIP_M_InspectionPoint','ShapeAttributes') IS NULL
 OR COL_LENGTH('dbo.PIP_M_InspectionPoint','StrokeWidth') IS NULL
BEGIN
    RAISERROR('Required coordinate/shape columns are missing. Run the coordinate and shape migrations first.',16,1);
    RETURN;
END;

IF OBJECT_ID('tempdb..#SourcePoints') IS NOT NULL DROP TABLE #SourcePoints;
CREATE TABLE #SourcePoints
(
    SourceSheet VARCHAR(20) NOT NULL,
    MapID BIGINT NOT NULL,
    PointCode VARCHAR(50) NOT NULL,
    PointName NVARCHAR(200) NOT NULL,
    MapX DECIMAL(9,4) NOT NULL,
    MapY DECIMAL(9,4) NOT NULL,
    ShapeType VARCHAR(20) NOT NULL,
    SvgPathData NVARCHAR(8000) NULL,
    ShapeAttributes NVARCHAR(2000) NOT NULL,
    StrokeWidth DECIMAL(6,2) NOT NULL,
    DisplayOrder INT NOT NULL,
    PointDescription NVARCHAR(200) NOT NULL,
    ObjectReferenceID VARCHAR(50) NOT NULL,
    ObjectReferenceCode VARCHAR(100) NOT NULL
);

