/* Validate all expected target tables/columns before opening the transaction. */
IF OBJECT_ID('dbo.INSPEC_M_LightingMap','U') IS NULL
BEGIN
    RAISERROR('dbo.INSPEC_M_LightingMap was not found.',16,1);
    RETURN;
END;
IF OBJECT_ID('dbo.INSPEC_M_ParkingMap','U') IS NULL
BEGIN
    RAISERROR('dbo.INSPEC_M_ParkingMap was not found.',16,1);
    RETURN;
END;
IF OBJECT_ID('dbo.PIP_M_InspectionPoint','U') IS NULL
BEGIN
    RAISERROR('dbo.PIP_M_InspectionPoint was not found.',16,1);
    RETURN;
END;

IF COL_LENGTH('dbo.INSPEC_M_LightingMap','MapID') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','CompanyID') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','LocationID') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','MapCode') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','MapName') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','ImagePath') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','ViewBoxX') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','ViewBoxY') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','ViewBoxWidth') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','ViewBoxHeight') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','MapVersion') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','IsActive') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','Description') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','CreatedBy') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','CreatedDate') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','UpdatedBy') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','UpdatedDate') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_LightingMap','IsCurrentVersion') IS NULL
BEGIN
    RAISERROR('INSPEC_M_LightingMap schema does not match the columns supplied in chat.',16,1);
    RETURN;
END;

IF COL_LENGTH('dbo.INSPEC_M_ParkingMap','MapID') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','CompanyID') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','LocationID') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','MapCode') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','MapName') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','FloorCode') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','ImagePath') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','ViewBoxX') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','ViewBoxY') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','ViewBoxWidth') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','ViewBoxHeight') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','MapVersion') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','IsCurrentVersion') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','IsActive') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','Description') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','CreatedBy') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','CreatedDate') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','UpdatedBy') IS NULL
 OR COL_LENGTH('dbo.INSPEC_M_ParkingMap','UpdatedDate') IS NULL
BEGIN
    RAISERROR('INSPEC_M_ParkingMap schema does not match the columns supplied in chat.',16,1);
    RETURN;
END;

IF EXISTS
(
    SELECT 1 FROM #SourcePoints
    WHERE MapX < 0 OR MapX > 100 OR MapY < 0 OR MapY > 100
       OR ShapeType NOT IN ('CIRCLE','PATH')
)
BEGIN
    RAISERROR('Invalid coordinate or unsupported ShapeType in point staging.',16,1);
    RETURN;
END;

IF EXISTS
(
    SELECT MapID,PointCode FROM #SourcePoints
    GROUP BY MapID,PointCode HAVING COUNT(*) > 1
)
BEGIN
    RAISERROR('Duplicate MapID + PointCode exists in workbook staging data.',16,1);
    RETURN;
END;

IF EXISTS
(
    SELECT 1
    FROM (SELECT DISTINCT MapID FROM #SourcePoints) P
    LEFT JOIN #SourceMaps M ON M.SourceMapID=P.MapID
    WHERE M.SourceMapID IS NULL
)
OR EXISTS
(
    SELECT 1 FROM #SourceMaps M
    LEFT JOIN (SELECT DISTINCT MapID FROM #SourcePoints) P ON P.MapID=M.SourceMapID
    WHERE P.MapID IS NULL
)
BEGIN
    RAISERROR('Source workbook MapID values do not match the six supplied map masters.',16,1);
    RETURN;
END;

BEGIN TRY
    BEGIN TRANSACTION;

    /* Prevent an existing MapID or MapCode from silently pointing to another physical map. */
    IF EXISTS
    (
        SELECT 1
        FROM #SourceMaps S
        INNER JOIN dbo.INSPEC_M_LightingMap M WITH (UPDLOCK,HOLDLOCK)
          ON S.SourceSheet='LIGHTNING' AND M.MapID=S.SourceMapID
        WHERE M.CompanyID<>'I00024012' OR M.LocationID<>'R02' OR M.MapCode<>S.MapCode
    )
    OR EXISTS
    (
        SELECT 1
        FROM #SourceMaps S
        INNER JOIN dbo.INSPEC_M_LightingMap M WITH (UPDLOCK,HOLDLOCK)
          ON S.SourceSheet='LIGHTNING' AND M.CompanyID='I00024012'
         AND M.LocationID='R02' AND M.MapCode=S.MapCode
         AND M.IsActive=1 AND M.IsCurrentVersion=1
        WHERE M.MapID<>S.SourceMapID
    )
    BEGIN
        RAISERROR('Lighting MapID/MapCode conflict. Check INSPEC_M_LightingMap before import.',16,1);
    END;

    IF EXISTS
    (
        SELECT 1
        FROM #SourceMaps S
        INNER JOIN dbo.INSPEC_M_ParkingMap M WITH (UPDLOCK,HOLDLOCK)
          ON S.SourceSheet='CARPARK' AND M.MapID=S.SourceMapID
        WHERE M.CompanyID<>'I00024012' OR M.LocationID<>'R02' OR M.MapCode<>S.MapCode
    )
    OR EXISTS
    (
        SELECT 1
        FROM #SourceMaps S
        INNER JOIN dbo.INSPEC_M_ParkingMap M WITH (UPDLOCK,HOLDLOCK)
          ON S.SourceSheet='CARPARK' AND M.CompanyID='I00024012'
         AND M.LocationID='R02' AND M.MapCode=S.MapCode
         AND M.IsActive=1 AND M.IsCurrentVersion=1
        WHERE M.MapID<>S.SourceMapID
    )
    BEGIN
        RAISERROR('Parking MapID/MapCode conflict. Check INSPEC_M_ParkingMap before import.',16,1);
    END;

    /* Insert missing Lighting master rows using the fixed IDs supplied by the user. */
    IF COLUMNPROPERTY(OBJECT_ID('dbo.INSPEC_M_LightingMap'),'MapID','IsIdentity')=1
    BEGIN
        SET IDENTITY_INSERT dbo.INSPEC_M_LightingMap ON;
        INSERT INTO dbo.INSPEC_M_LightingMap
        (MapID,CompanyID,LocationID,MapCode,MapName,ImagePath,ViewBoxX,ViewBoxY,
         ViewBoxWidth,ViewBoxHeight,MapVersion,IsActive,Description,CreatedBy,
         CreatedDate,UpdatedBy,UpdatedDate,IsCurrentVersion)
        SELECT S.SourceMapID,'I00024012','R02',S.MapCode,S.MapName,S.ImagePath,
               S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,S.MapVersion,
               S.IsActive,S.Description,S.CreatedBy,S.CreatedDate,S.UpdatedBy,
               S.UpdatedDate,S.IsCurrentVersion
        FROM #SourceMaps S
        WHERE S.SourceSheet='LIGHTNING'
          AND NOT EXISTS (SELECT 1 FROM dbo.INSPEC_M_LightingMap M WITH (UPDLOCK,HOLDLOCK)
                          WHERE M.MapID=S.SourceMapID);
        SET IDENTITY_INSERT dbo.INSPEC_M_LightingMap OFF;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.INSPEC_M_LightingMap
        (MapID,CompanyID,LocationID,MapCode,MapName,ImagePath,ViewBoxX,ViewBoxY,
         ViewBoxWidth,ViewBoxHeight,MapVersion,IsActive,Description,CreatedBy,
         CreatedDate,UpdatedBy,UpdatedDate,IsCurrentVersion)
        SELECT S.SourceMapID,'I00024012','R02',S.MapCode,S.MapName,S.ImagePath,
               S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,S.MapVersion,
               S.IsActive,S.Description,S.CreatedBy,S.CreatedDate,S.UpdatedBy,
               S.UpdatedDate,S.IsCurrentVersion
        FROM #SourceMaps S
        WHERE S.SourceSheet='LIGHTNING'
          AND NOT EXISTS (SELECT 1 FROM dbo.INSPEC_M_LightingMap M WITH (UPDLOCK,HOLDLOCK)
                          WHERE M.MapID=S.SourceMapID);
    END;

    /* Insert missing Parking master rows using the fixed IDs supplied by the user. */
    IF COLUMNPROPERTY(OBJECT_ID('dbo.INSPEC_M_ParkingMap'),'MapID','IsIdentity')=1
    BEGIN
        SET IDENTITY_INSERT dbo.INSPEC_M_ParkingMap ON;
        INSERT INTO dbo.INSPEC_M_ParkingMap
        (MapID,CompanyID,LocationID,MapCode,MapName,FloorCode,ImagePath,ViewBoxX,
         ViewBoxY,ViewBoxWidth,ViewBoxHeight,MapVersion,IsCurrentVersion,IsActive,
         Description,CreatedBy,CreatedDate,UpdatedBy,UpdatedDate)
        SELECT S.SourceMapID,'I00024012','R02',S.MapCode,S.MapName,S.FloorCode,S.ImagePath,
               S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,S.MapVersion,
               S.IsCurrentVersion,S.IsActive,S.Description,S.CreatedBy,S.CreatedDate,
               S.UpdatedBy,S.UpdatedDate
        FROM #SourceMaps S
        WHERE S.SourceSheet='CARPARK'
          AND NOT EXISTS (SELECT 1 FROM dbo.INSPEC_M_ParkingMap M WITH (UPDLOCK,HOLDLOCK)
                          WHERE M.MapID=S.SourceMapID);
        SET IDENTITY_INSERT dbo.INSPEC_M_ParkingMap OFF;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.INSPEC_M_ParkingMap
        (MapID,CompanyID,LocationID,MapCode,MapName,FloorCode,ImagePath,ViewBoxX,
         ViewBoxY,ViewBoxWidth,ViewBoxHeight,MapVersion,IsCurrentVersion,IsActive,
         Description,CreatedBy,CreatedDate,UpdatedBy,UpdatedDate)
        SELECT S.SourceMapID,'I00024012','R02',S.MapCode,S.MapName,S.FloorCode,S.ImagePath,
               S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,S.MapVersion,
               S.IsCurrentVersion,S.IsActive,S.Description,S.CreatedBy,S.CreatedDate,
               S.UpdatedBy,S.UpdatedDate
        FROM #SourceMaps S
        WHERE S.SourceSheet='CARPARK'
          AND NOT EXISTS (SELECT 1 FROM dbo.INSPEC_M_ParkingMap M WITH (UPDLOCK,HOLDLOCK)
                          WHERE M.MapID=S.SourceMapID);
    END;

    /* Align mutable map metadata to the supplied rows; preserve original Created* audit data. */
    UPDATE M
       SET M.MapCode=S.MapCode,
           M.MapName=S.MapName,
           M.ImagePath=S.ImagePath,
           M.ViewBoxX=S.ViewBoxX,
           M.ViewBoxY=S.ViewBoxY,
           M.ViewBoxWidth=S.ViewBoxWidth,
           M.ViewBoxHeight=S.ViewBoxHeight,
           M.MapVersion=S.MapVersion,
           M.IsActive=S.IsActive,
           M.Description=S.Description,
           M.IsCurrentVersion=S.IsCurrentVersion,
           M.UpdatedBy=@UserID,
           M.UpdatedDate=GETDATE()
    FROM dbo.INSPEC_M_LightingMap M
    INNER JOIN #SourceMaps S ON S.SourceSheet='LIGHTNING' AND S.SourceMapID=M.MapID
    WHERE M.CompanyID='I00024012' AND M.LocationID='R02'
      AND (M.MapCode<>S.MapCode OR M.MapName<>S.MapName OR ISNULL(M.ImagePath,'')<>S.ImagePath
        OR ISNULL(M.ViewBoxX,0)<>S.ViewBoxX OR ISNULL(M.ViewBoxY,0)<>S.ViewBoxY
        OR ISNULL(M.ViewBoxWidth,0)<>S.ViewBoxWidth OR ISNULL(M.ViewBoxHeight,0)<>S.ViewBoxHeight
        OR ISNULL(M.MapVersion,0)<>S.MapVersion OR ISNULL(M.IsActive,0)<>S.IsActive
        OR ISNULL(M.IsCurrentVersion,0)<>S.IsCurrentVersion
        OR ISNULL(M.Description,'')<>ISNULL(S.Description,''));

    UPDATE M
       SET M.MapCode=S.MapCode,
           M.MapName=S.MapName,
           M.FloorCode=S.FloorCode,
           M.ImagePath=S.ImagePath,
           M.ViewBoxX=S.ViewBoxX,
           M.ViewBoxY=S.ViewBoxY,
           M.ViewBoxWidth=S.ViewBoxWidth,
           M.ViewBoxHeight=S.ViewBoxHeight,
           M.MapVersion=S.MapVersion,
           M.IsCurrentVersion=S.IsCurrentVersion,
           M.IsActive=S.IsActive,
           M.Description=S.Description,
           M.UpdatedBy=@UserID,
           M.UpdatedDate=GETDATE()
    FROM dbo.INSPEC_M_ParkingMap M
    INNER JOIN #SourceMaps S ON S.SourceSheet='CARPARK' AND S.SourceMapID=M.MapID
    WHERE M.CompanyID='I00024012' AND M.LocationID='R02'
      AND (M.MapCode<>S.MapCode OR M.MapName<>S.MapName OR ISNULL(M.FloorCode,'')<>ISNULL(S.FloorCode,'')
        OR ISNULL(M.ImagePath,'')<>S.ImagePath
        OR ISNULL(M.ViewBoxX,0)<>S.ViewBoxX OR ISNULL(M.ViewBoxY,0)<>S.ViewBoxY
        OR ISNULL(M.ViewBoxWidth,0)<>S.ViewBoxWidth OR ISNULL(M.ViewBoxHeight,0)<>S.ViewBoxHeight
        OR ISNULL(M.MapVersion,0)<>S.MapVersion OR ISNULL(M.IsActive,0)<>S.IsActive
        OR ISNULL(M.IsCurrentVersion,0)<>S.IsCurrentVersion
        OR ISNULL(M.Description,'')<>ISNULL(S.Description,''));

    /* Every source map must now resolve to the exact requested master row. */
    IF EXISTS
    (
        SELECT 1
        FROM #SourceMaps S
        LEFT JOIN dbo.INSPEC_M_LightingMap M
          ON S.SourceSheet='LIGHTNING' AND M.MapID=S.SourceMapID
         AND M.CompanyID='I00024012' AND M.LocationID='R02' AND M.MapCode=S.MapCode
         AND M.IsActive=1 AND M.IsCurrentVersion=1
        WHERE S.SourceSheet='LIGHTNING' AND M.MapID IS NULL
    )
    OR EXISTS
    (
        SELECT 1
        FROM #SourceMaps S
        LEFT JOIN dbo.INSPEC_M_ParkingMap M
          ON S.SourceSheet='CARPARK' AND M.MapID=S.SourceMapID
         AND M.CompanyID='I00024012' AND M.LocationID='R02' AND M.MapCode=S.MapCode
         AND M.IsActive=1 AND M.IsCurrentVersion=1
        WHERE S.SourceSheet='CARPARK' AND M.MapID IS NULL
    )
    BEGIN
        RAISERROR('One or more source MapIDs did not resolve in the Lighting/Parking master tables.',16,1);
    END;

    /*
       PIP_M_InspectionPoint.MapID has FK FK_PIP_M_InspectionPoint_Map
       to dbo.PIP_M_InspectionMap. INSPEC_M_LightingMap and INSPEC_M_ParkingMap
       are separate masters and do NOT satisfy that FK by themselves.
       Mirror the six map definitions into PIP_M_InspectionMap using the same
       MapIDs so point rows can reference them without changing their IDs.
    */
    IF OBJECT_ID('dbo.PIP_M_InspectionMap','U') IS NULL
    BEGIN
        RAISERROR('dbo.PIP_M_InspectionMap was not found. It is required by FK_PIP_M_InspectionPoint_Map.',16,1);
    END;

    IF COL_LENGTH('dbo.PIP_M_InspectionMap','MapID') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','CompanyID') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','LocationID') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','MapCode') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','MapName') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','ImagePath') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','ViewBoxX') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','ViewBoxY') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','ViewBoxWidth') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','ViewBoxHeight') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','MapVersion') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','InspectionTypeCode') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','InspectionTypeDetailCode') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','RequireAllPoints') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','IsCurrentVersion') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','IsActive') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','Description') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','EntryUser') IS NULL
     OR COL_LENGTH('dbo.PIP_M_InspectionMap','UpdateUser') IS NULL
    BEGIN
        RAISERROR('dbo.PIP_M_InspectionMap does not contain the columns required by the existing INSPEC map seed pattern.',16,1);
    END;

    IF OBJECT_ID('tempdb..#PipMaps') IS NOT NULL DROP TABLE #PipMaps;
    CREATE TABLE #PipMaps
    (
        MapID BIGINT NOT NULL PRIMARY KEY,
        CompanyID VARCHAR(10) NOT NULL,
        LocationID VARCHAR(3) NOT NULL,
        MapCode VARCHAR(50) NOT NULL,
        MapName NVARCHAR(200) NOT NULL,
        ImagePath NVARCHAR(500) NOT NULL,
        ViewBoxX DECIMAL(18,4) NOT NULL,
        ViewBoxY DECIMAL(18,4) NOT NULL,
        ViewBoxWidth DECIMAL(18,4) NOT NULL,
        ViewBoxHeight DECIMAL(18,4) NOT NULL,
        MapVersion INT NOT NULL,
        InspectionTypeCode VARCHAR(2) NOT NULL,
        InspectionTypeDetailCode VARCHAR(20) NOT NULL,
        RequireAllPoints BIT NOT NULL,
        IsCurrentVersion BIT NOT NULL,
        IsActive BIT NOT NULL,
        Description NVARCHAR(500) NOT NULL,
        EntryUser VARCHAR(50) NOT NULL,
        UpdateUser VARCHAR(50) NOT NULL
    );

    INSERT INTO #PipMaps
    (MapID,CompanyID,LocationID,MapCode,MapName,ImagePath,
     ViewBoxX,ViewBoxY,ViewBoxWidth,ViewBoxHeight,MapVersion,
     InspectionTypeCode,InspectionTypeDetailCode,RequireAllPoints,
     IsCurrentVersion,IsActive,Description,EntryUser,UpdateUser)
    SELECT S.SourceMapID,'I00024012','R02',S.MapCode,S.MapName,S.ImagePath,
           S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,S.MapVersion,
           CASE WHEN S.SourceSheet='LIGHTNING' THEN 'LT' ELSE 'CP' END,
           CASE WHEN S.SourceSheet='LIGHTNING' THEN 'MCDP-LT'
                WHEN S.SourceMapID=4 THEN 'MCDP-CP-B2'
                WHEN S.SourceMapID=5 THEN 'MCDP-CP-B3'
                WHEN S.SourceMapID=6 THEN 'MCDP-CP-B1'
                ELSE 'MCDP-CP' END,
           0,S.IsCurrentVersion,S.IsActive,
           ISNULL(S.Description,N'Imported from INSPEC map master.'),
           ISNULL(NULLIF(S.CreatedBy,''),@UserID),
           ISNULL(NULLIF(S.UpdatedBy,''),@UserID)
    FROM #SourceMaps S;

    /* Do not reuse a fixed PIP MapID if it is occupied by a different map. */
    IF EXISTS
    (
        SELECT 1
        FROM #PipMaps S
        INNER JOIN dbo.PIP_M_InspectionMap M WITH (UPDLOCK,HOLDLOCK)
          ON M.MapID=S.MapID
        WHERE M.CompanyID<>S.CompanyID OR M.LocationID<>S.LocationID
           OR M.MapCode<>S.MapCode
    )
    BEGIN
        RAISERROR('PIP_M_InspectionMap MapID collision: one of IDs 1,3,4,5,6,7 is already assigned to a different map. No points were inserted.',16,1);
    END;

    IF EXISTS
    (
        SELECT 1
        FROM #PipMaps S
        INNER JOIN dbo.PIP_M_InspectionMap M WITH (UPDLOCK,HOLDLOCK)
          ON M.CompanyID=S.CompanyID AND M.LocationID=S.LocationID
         AND M.MapCode=S.MapCode
        WHERE M.MapID<>S.MapID
    )
    BEGIN
        RAISERROR('PIP_M_InspectionMap MapCode collision: map exists under a different MapID. Reconcile map IDs before importing points.',16,1);
    END;

    /* Insert the PIP FK parent rows with exact MapIDs from the two INSPEC masters. */
    IF COLUMNPROPERTY(OBJECT_ID('dbo.PIP_M_InspectionMap'),'MapID','IsIdentity')=1
    BEGIN
        SET IDENTITY_INSERT dbo.PIP_M_InspectionMap ON;
        INSERT INTO dbo.PIP_M_InspectionMap
        (MapID,CompanyID,LocationID,MapCode,MapName,ImagePath,
         ViewBoxX,ViewBoxY,ViewBoxWidth,ViewBoxHeight,MapVersion,
         InspectionTypeCode,InspectionTypeDetailCode,RequireAllPoints,
         IsCurrentVersion,IsActive,Description,EntryUser,UpdateUser)
        SELECT S.MapID,S.CompanyID,S.LocationID,S.MapCode,S.MapName,S.ImagePath,
               S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,S.MapVersion,
               S.InspectionTypeCode,S.InspectionTypeDetailCode,S.RequireAllPoints,
               S.IsCurrentVersion,S.IsActive,S.Description,S.EntryUser,S.UpdateUser
        FROM #PipMaps S
        WHERE NOT EXISTS (SELECT 1 FROM dbo.PIP_M_InspectionMap M WITH (UPDLOCK,HOLDLOCK)
                          WHERE M.MapID=S.MapID);
        SET IDENTITY_INSERT dbo.PIP_M_InspectionMap OFF;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.PIP_M_InspectionMap
        (MapID,CompanyID,LocationID,MapCode,MapName,ImagePath,
         ViewBoxX,ViewBoxY,ViewBoxWidth,ViewBoxHeight,MapVersion,
         InspectionTypeCode,InspectionTypeDetailCode,RequireAllPoints,
         IsCurrentVersion,IsActive,Description,EntryUser,UpdateUser)
        SELECT S.MapID,S.CompanyID,S.LocationID,S.MapCode,S.MapName,S.ImagePath,
               S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,S.MapVersion,
               S.InspectionTypeCode,S.InspectionTypeDetailCode,S.RequireAllPoints,
               S.IsCurrentVersion,S.IsActive,S.Description,S.EntryUser,S.UpdateUser
        FROM #PipMaps S
        WHERE NOT EXISTS (SELECT 1 FROM dbo.PIP_M_InspectionMap M WITH (UPDLOCK,HOLDLOCK)
                          WHERE M.MapID=S.MapID);
    END;

    /* Keep matching PIP map rows aligned with the supplied map master metadata. */
    UPDATE M
       SET M.MapCode=S.MapCode,
           M.MapName=S.MapName,
           M.ImagePath=S.ImagePath,
           M.ViewBoxX=S.ViewBoxX,
           M.ViewBoxY=S.ViewBoxY,
           M.ViewBoxWidth=S.ViewBoxWidth,
           M.ViewBoxHeight=S.ViewBoxHeight,
           M.MapVersion=S.MapVersion,
           M.InspectionTypeCode=S.InspectionTypeCode,
           M.InspectionTypeDetailCode=S.InspectionTypeDetailCode,
           M.RequireAllPoints=S.RequireAllPoints,
           M.IsCurrentVersion=S.IsCurrentVersion,
           M.IsActive=S.IsActive,
           M.Description=S.Description,
           M.UpdateUser=@UserID
    FROM dbo.PIP_M_InspectionMap M
    INNER JOIN #PipMaps S ON S.MapID=M.MapID
    WHERE M.CompanyID=S.CompanyID AND M.LocationID=S.LocationID;

    IF EXISTS
    (
        SELECT 1
        FROM #PipMaps S
        LEFT JOIN dbo.PIP_M_InspectionMap M
          ON M.MapID=S.MapID AND M.CompanyID=S.CompanyID
         AND M.LocationID=S.LocationID AND M.MapCode=S.MapCode
         AND M.IsActive=1 AND M.IsCurrentVersion=1
        WHERE M.MapID IS NULL
    )
    BEGIN
        RAISERROR('One or more MapIDs could not be resolved in dbo.PIP_M_InspectionMap. Point import cancelled.',16,1);
    END;

    /* Source MapID is already the target MapID in the supplied master tables. */
    IF OBJECT_ID('tempdb..#MapIDMap') IS NOT NULL DROP TABLE #MapIDMap;
    CREATE TABLE #MapIDMap
    (
        SourceMapID INT NOT NULL PRIMARY KEY,
        MapID BIGINT NOT NULL UNIQUE
    );
    INSERT INTO #MapIDMap(SourceMapID,MapID)
    SELECT SourceMapID,SourceMapID FROM #SourceMaps;

    /* Assign deterministic InspectionPointID values starting at 1. */
    IF OBJECT_ID('tempdb..#DesiredPointIDs') IS NOT NULL DROP TABLE #DesiredPointIDs;
    CREATE TABLE #DesiredPointIDs
    (
        InspectionPointID BIGINT NOT NULL PRIMARY KEY,
        MapID BIGINT NOT NULL,
        PointCode VARCHAR(50) NOT NULL,
        UNIQUE(MapID,PointCode)
    );
    INSERT INTO #DesiredPointIDs(InspectionPointID,MapID,PointCode)
    SELECT ROW_NUMBER() OVER (ORDER BY S.MapID,S.DisplayOrder,S.PointCode),
           S.MapID,S.PointCode
    FROM #SourcePoints S;

    /* Avoid changing an existing point's primary key or overwriting another point. */
    IF EXISTS
    (
        SELECT 1
        FROM dbo.PIP_M_InspectionPoint P
        INNER JOIN #DesiredPointIDs D ON D.InspectionPointID=P.InspectionPointID
        WHERE P.MapID<>D.MapID OR P.PointCode<>D.PointCode
    )
    BEGIN
        RAISERROR('InspectionPointID 1..798 already belongs to other points. Clear/reconcile those IDs before import.',16,1);
    END;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.PIP_M_InspectionPoint P
        INNER JOIN #DesiredPointIDs D ON D.MapID=P.MapID AND D.PointCode=P.PointCode
        WHERE P.InspectionPointID<>D.InspectionPointID
    )
    BEGIN
        RAISERROR('One or more imported MapID + PointCode rows already have a different InspectionPointID. Reconcile IDs before import.',16,1);
    END;

    /* Update existing rows without changing their deterministic primary keys. */
    UPDATE P
       SET P.PointName=S.PointName,
           P.PointObjectType='GENERAL',
           P.PointDescription=S.PointDescription,
           P.ObjectReferenceType='GENERAL',
           P.ObjectReferenceID=S.ObjectReferenceID,
           P.ObjectReferenceCode=S.ObjectReferenceCode,
           P.MapX=S.MapX,
           P.MapY=S.MapY,
           P.ShapeType=S.ShapeType,
           P.SvgPathData=S.SvgPathData,
           P.ShapeAttributes=S.ShapeAttributes,
           P.StrokeWidth=S.StrokeWidth,
           P.DisplayOrder=S.DisplayOrder,
           P.IsActive=1,
           P.UpdateUser=@UserID
    FROM dbo.PIP_M_InspectionPoint P
    INNER JOIN #SourcePoints S ON S.MapID=P.MapID AND S.PointCode=P.PointCode;

    /* Insert missing rows. IDs are exactly 1..798, not MAX(InspectionPointID)+1. */
    IF COLUMNPROPERTY(OBJECT_ID('dbo.PIP_M_InspectionPoint'),'InspectionPointID','IsIdentity')=1
    BEGIN
        SET IDENTITY_INSERT dbo.PIP_M_InspectionPoint ON;
        INSERT INTO dbo.PIP_M_InspectionPoint
        (InspectionPointID,PointCode,PointName,PointObjectType,PointDescription,
         ObjectReferenceType,ObjectReferenceID,ObjectReferenceCode,MapID,MapX,MapY,
         ShapeType,SvgPathData,ShapeAttributes,StrokeWidth,DisplayOrder,IsActive,
         IsNormalAbnormalRequired,EntryUser,UpdateUser)
        SELECT D.InspectionPointID,S.PointCode,S.PointName,'GENERAL',S.PointDescription,
               'GENERAL',S.ObjectReferenceID,S.ObjectReferenceCode,D.MapID,S.MapX,S.MapY,
               S.ShapeType,S.SvgPathData,S.ShapeAttributes,S.StrokeWidth,S.DisplayOrder,
               1,0,@UserID,@UserID
        FROM #SourcePoints S
        INNER JOIN #DesiredPointIDs D ON D.MapID=S.MapID AND D.PointCode=S.PointCode
        WHERE NOT EXISTS (SELECT 1 FROM dbo.PIP_M_InspectionPoint P
                          WHERE P.InspectionPointID=D.InspectionPointID);
        SET IDENTITY_INSERT dbo.PIP_M_InspectionPoint OFF;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.PIP_M_InspectionPoint
        (InspectionPointID,PointCode,PointName,PointObjectType,PointDescription,
         ObjectReferenceType,ObjectReferenceID,ObjectReferenceCode,MapID,MapX,MapY,
         ShapeType,SvgPathData,ShapeAttributes,StrokeWidth,DisplayOrder,IsActive,
         IsNormalAbnormalRequired,EntryUser,UpdateUser)
        SELECT D.InspectionPointID,S.PointCode,S.PointName,'GENERAL',S.PointDescription,
               'GENERAL',S.ObjectReferenceID,S.ObjectReferenceCode,D.MapID,S.MapX,S.MapY,
               S.ShapeType,S.SvgPathData,S.ShapeAttributes,S.StrokeWidth,S.DisplayOrder,
               1,0,@UserID,@UserID
        FROM #SourcePoints S
        INNER JOIN #DesiredPointIDs D ON D.MapID=S.MapID AND D.PointCode=S.PointCode
        WHERE NOT EXISTS (SELECT 1 FROM dbo.PIP_M_InspectionPoint P
                          WHERE P.InspectionPointID=D.InspectionPointID);
    END;

    /* Preview map-to-point mapping and primary-key sequence. */
    SELECT S.SourceSheet,S.SourceMapID AS MapID,S.MapCode,S.MapName,S.ImagePath,
           S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight,
           COUNT(P.InspectionPointID) AS ActivePointCount
    FROM #SourceMaps S
    LEFT JOIN #DesiredPointIDs D ON D.MapID=S.SourceMapID
    LEFT JOIN dbo.PIP_M_InspectionPoint P
      ON P.MapID=D.MapID AND P.PointCode=D.PointCode AND P.IsActive=1
    GROUP BY S.SourceSheet,S.SourceMapID,S.MapCode,S.MapName,S.ImagePath,
             S.ViewBoxX,S.ViewBoxY,S.ViewBoxWidth,S.ViewBoxHeight
    ORDER BY S.SourceMapID;

    SELECT MIN(P.InspectionPointID) AS FirstInspectionPointID,
           MAX(P.InspectionPointID) AS LastInspectionPointID,
           COUNT(*) AS ImportedPointCount
    FROM dbo.PIP_M_InspectionPoint P
    INNER JOIN #DesiredPointIDs D ON D.InspectionPointID=P.InspectionPointID
                                 AND D.MapID=P.MapID AND D.PointCode=P.PointCode;

    SELECT P.InspectionPointID,P.MapID,P.PointCode,P.PointName,P.MapX,P.MapY,
           P.ShapeType,P.StrokeWidth,P.DisplayOrder
    FROM dbo.PIP_M_InspectionPoint P
    INNER JOIN #DesiredPointIDs D ON D.InspectionPointID=P.InspectionPointID
                                 AND D.MapID=P.MapID AND D.PointCode=P.PointCode
    ORDER BY P.InspectionPointID;

    IF @ApplyChanges=1
    BEGIN
        COMMIT TRANSACTION;
        PRINT 'Import committed.';
    END
    ELSE
    BEGIN
        ROLLBACK TRANSACTION;
        PRINT 'PREVIEW ONLY: transaction rolled back. Set @ApplyChanges = 1 to commit.';
    END;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
    BEGIN TRY
        IF COLUMNPROPERTY(OBJECT_ID('dbo.INSPEC_M_LightingMap'),'MapID','IsIdentity')=1
            SET IDENTITY_INSERT dbo.INSPEC_M_LightingMap OFF;
    END TRY BEGIN CATCH END CATCH;
    BEGIN TRY
        IF COLUMNPROPERTY(OBJECT_ID('dbo.INSPEC_M_ParkingMap'),'MapID','IsIdentity')=1
            SET IDENTITY_INSERT dbo.INSPEC_M_ParkingMap OFF;
    END TRY BEGIN CATCH END CATCH;
    BEGIN TRY
        IF COLUMNPROPERTY(OBJECT_ID('dbo.PIP_M_InspectionMap'),'MapID','IsIdentity')=1
            SET IDENTITY_INSERT dbo.PIP_M_InspectionMap OFF;
    END TRY BEGIN CATCH END CATCH;
    BEGIN TRY
        IF COLUMNPROPERTY(OBJECT_ID('dbo.PIP_M_InspectionPoint'),'InspectionPointID','IsIdentity')=1
            SET IDENTITY_INSERT dbo.PIP_M_InspectionPoint OFF;
    END TRY BEGIN CATCH END CATCH;
    DECLARE @ErrMsg NVARCHAR(4000);
    DECLARE @ErrSeverity INT;
    DECLARE @ErrState INT;
    SELECT @ErrMsg=ERROR_MESSAGE(),@ErrSeverity=ERROR_SEVERITY(),@ErrState=ERROR_STATE();
    RAISERROR(@ErrMsg,@ErrSeverity,@ErrState);
    RETURN;
END CATCH;
